export interface Row {
  name: string;
  age: number;
  city: string;
}

type Direction = "asc" | "desc";
type SortState = { column: keyof Row; direction: Direction } | null;

const COLUMNS: Array<{ key: keyof Row; label: string; numeric: boolean }> = [
  { key: "name", label: "Name", numeric: false },
  { key: "age", label: "Age", numeric: true },
  { key: "city", label: "City", numeric: false },
];

/** Click cycle: ascending -> descending -> unsorted. */
function nextSort(current: SortState, column: keyof Row): SortState {
  if (!current || current.column !== column) {
    return { column, direction: "asc" };
  }
  if (current.direction === "asc") return { column, direction: "desc" };
  return null;
}

function compare(a: Row, b: Row, column: keyof Row, numeric: boolean): number {
  const av = a[column];
  const bv = b[column];
  if (numeric) {
    return (av as number) - (bv as number);
  }
  return String(av).localeCompare(String(bv));
}

export function DataGrid({ rows }: { rows: Row[] }) {
  const [sort, setSort] = useState<SortState>(null);
  const liveRegionId = useId();

  const sorted = useMemo(() => {
    if (!sort) return rows;
    const meta = COLUMNS.find((c) => c.key === sort.column)!;
    const cmp = (a: Row, b: Row) => compare(a, b, sort.column, meta.numeric);
    const result = [...rows].sort(cmp);
    if (sort.direction === "desc") result.reverse();
    return result;
  }, [rows, sort]);

  const announcement =
    sort === null
      ? "Unsorted"
      : `Sorted by ${sort.column} ${sort.direction === "asc" ? "ascending" : "descending"}`;

  return (
    <div>
      {/* Visually hidden live region announcing the current sort state */}
      <div
        id={liveRegionId}
        role="status"
        aria-live="polite"
        style={{
          position: "absolute",
          width: 1,
          height: 1,
          margin: -1,
          padding: 0,
          overflow: "hidden",
          clip: "rect(0 0 0 0)",
          whiteSpace: "nowrap",
          border: 0,
        }}
      >
        {announcement}
      </div>

      <table>
        <thead>
          <tr>
            {COLUMNS.map(({ key, label }) => {
              const isSorted = sort?.column === key;
              const ariaSort = isSorted ? (sort!.direction === "asc" ? "ascending" : "descending") : undefined;
              return (
                <th
                  key={key}
                  scope="col"
                  aria-sort={ariaSort}
                >
                  <button
                    type="button"
                    onClick={() => setSort(nextSort(sort, key))}
                  >
                    {label}
                    {isSorted ? (sort!.direction === "asc" ? " ▲" : " ▼") : ""}
                  </button>
                </th>
              );
            })}
          </tr>
        </thead>
        <tbody>
          {sorted.map((row) => (
            <tr key={`${row.name}-${row.age}-${row.city}`}>
              <td>{row.name}</td>
              <td>{row.age}</td>
              <td>{row.city}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
"})
