result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/grid-sort/test/DataGrid.test.tsx", "content": "import { describe, expect, it } from "vitest";
import { render, screen, within } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { DataGrid, type Row } from "../src/DataGrid";

const ROWS: Row[] = [
  { name: "Dana", age: 9, city: "Zurich" },
  { name: "Alice", age: 42, city: "Amsterdam" },
  { name: "Bob", age: 17, city: "kyiv" },
  { name: "Carol", age: 100, city: "berlin" },
];

const COLUMN_LABELS = ["Name", "Age", "City"] as const;
type ColumnKey = "Name" | "Age" | "City";

/** Column values for each column label, in the order rows were passed in. */
function columnValues(label: ColumnKey): string[] {
  const index = COLUMN_LABELS.indexOf(label);
  return ROWS.map((row) => {
    const key = (["name", "age", "city"] as const)[index];
    return String(row[key]);
  });
}

function expectedOrder(label: ColumnKey, direction: "asc" | "desc"): string[] {
  const numeric = label === "Age";
  const values = columnValues(label);
  const indices = values.map((_, i) => i);
  indices.sort((i, j) => {
    const a = values[i];
    const b = values[j];
    const cmp = numeric ? Number(a) - Number(b) : a.localeCompare(b);
    return cmp || i - j; // stable tiebreak on original index
  });
  if (direction === "desc") indices.reverse();
  return indices.map((i) => values[i]);
}

async function clickHeader(label: ColumnKey) {
  await userEvent.click(screen.getByRole("button", { name: new RegExp(`^${label}`) }));
}

function readColumnCells(label: ColumnKey): string[] {
  // Read data cells by position within tbody, matching the header's column index.
  const table = screen.getByRole("table");
  const headers = within(table).getAllByRole("columnheader");
  const columnIndex = headers.findIndex((th) =>
    within(th).getByRole("button", { name: new RegExp(`^${label}`) })
  );
  const bodyRows = within(table).getAllByRole("row").slice(1); // skip header row
  return bodyRows.map((tr) => within(tr).getAllByRole("cell")[columnIndex].textContent!);
}

function getAriaSorts(): Array<string | null> {
  return within(screen.getByRole("table"))
    .getAllByRole("columnheader")
    .map((th) => th.getAttribute("aria-sort"));
}

describe("DataGrid sorting", () => {
  it("renders all rows initially with no aria-sort and no announcement of sorting", () => {
    render(<DataGrid rows={ROWS} />);
    expect(readColumnCells("Name")).toEqual(columnValues("Name"));
    expect(getAriaSorts()).toEqual([null, null, null]);
    expect(screen.getByRole("status")).toHaveTextContent(/^Unsorted$/);
  });

  it.each(COLUMN_LABELS)("cycles %s through asc -> desc -> unsorted with correct row order", async (label) => {
    render(<DataGrid rows={ROWS} />);

    await clickHeader(label);
    expect(readColumnCells(label)).toEqual(expectedOrder(label, "asc"));

    await clickHeader(label);
    expect(readColumnCells(label)).toEqual(expectedOrder(label, "desc"));

    await clickHeader(label);
    expect(readColumnCells(label)).toEqual(columnValues(label));
  });

  it.each(COLUMN_LABELS)(
    "%s sets aria-sort ascending then descending, and removes it after the full cycle",
    async (label) => {
      render(<DataGrid rows={ROWS} />);

      await clickHeader(label);
      const th = screen.getByRole("button", { name: new RegExp(`^${label}`) }).closest("th")!;
      expect(th).toHaveAttribute("aria-sort", "ascending");

      await clickHeader(label);
      expect(th).toHaveAttribute("aria-sort", "descending");

      await clickHeader(label);
      expect(th).not.toHaveAttribute("aria-sort");
    }
  );

  it.each(COLUMN_LABELS)("sorting by %s clears aria-sort from the other columns", async (label) => {
    render(<DataGrid rows={ROWS} />);
    const buttons = COLUMN_LABELS.map((l) =>
      screen.getByRole("button", { name: new RegExp(`^${l}`) })
    );
    const ths = buttons.map((b) => b.closest("th")!);

    // First sort by Name so every column has been through a known state.
    await clickHeader("Name");
    expect(ths.map((th) => th.getAttribute("aria-sort"))).toEqual([
      "ascending",
      null,
      null,
    ]);

    // Sorting another column must clear aria-sort everywhere else.
    await clickHeader(label === "Name" ? "Age" : label);
    const activeIndex = label === "Name" ? 1 : COLUMN_LABELS.indexOf(label);
    getAriaSorts().forEach((value, index) => {
      if (index === activeIndex) {
        expect(value).toBe("ascending");
      } else {
        expect(value).toBeNull();
      }
    });
    // Explicit exclusivity assertion: exactly one aria-sort present.
    const present = getAriaSorts().filter((v) => v !== null);
    expect(present).toHaveLength(1);
  });

  it("announces 'Sorted by age descending' in the live region", async () => {
    render(<DataGrid rows={ROWS} />);
    await clickHeader("Age"); // ascending
    await clickHeader("Age"); // descending
    expect(screen.getByRole("status")).toHaveTextContent("Sorted by age descending");
  });

  it("updates the live region through the whole cycle", async () => {
    render(<DataGrid rows={ROWS} />);

    await clickHeader("City");
    expect(screen.getByRole("status")).toHaveTextContent("Sorted by city ascending");

    await clickHeader("Name");
    expect(screen.getByRole("status")).toHaveTextContent("Sorted by name ascending");

    await clickHeader("Name");
    expect(screen.getByRole("status")).toHaveTextContent("Sorted by name descending");

    await clickHeader("Name");
    expect(screen.getByRole("status")).toHaveTextContent(/^Unsorted$/);
  });

  it("sorts numeric columns numerically, not lexically", async () => {
    render(
      <DataGrid
        rows={[
          { name: "a", age: 2, city: "x" },
          { name: "b", age: 10, city: "y" },
          { name: "c", age: 1, city: "z" },
        ]}
      />
    );

    await clickHeader("Age");
    expect(readColumnCells("Age")).toEqual(["1", "2", "10"]); // lexical would be ["1","10","2"]

    await clickHeader("Age");
    expect(readColumnCells("Age")).toEqual(["10", "2", "1"]);
  });
});
"})
